import random

BLOCK_SIZE = 10  # Example default, though passed as argument
SCREEN_WIDTH = 640  # Example
SCREEN_HEIGHT = 480  # Example

SCORE_PER_FOOD = 100
MAX_HEAD_OFFSET_CHECK = 2


class Snake:
    def __init__(self, screen_width, screen_height, block_size, food_position):
        self.length = 1
        self.screen_width = screen_width
        self.screen_height = screen_height
        self.block_size = block_size
        self._positions = [((screen_width / 2), (screen_height / 2))]
        self.score = 0
        self._food_position = food_position

    @property
    def positions(self):
        return self._positions

    def _set_positions(self, positions):
        self._positions = positions

    positions = property(fget=positions, fset=_set_positions)

    @property
    def food_position(self):
        return self._food_position

    def _set_food_position(self, pos):
        self._food_position = pos

    food_position = property(fget=food_position, fset=_set_food_position)

    def move(self, direction):
        x, y = direction
        new = self._calculate_new_position(direction)

        if self._is_food(new):
            self.eat_food()

        if self._collides_with_body(new):
            self.reset()
        else:
            self._update_positions(new)

    def _calculate_new_position(self, direction):
        cur = self.positions[0]
        x, y = direction
        return (
            ((cur[0] + (x * self.block_size)) % self.screen_width),
            (cur[1] + (y * self.block_size)) % self.screen_height,
        )

    def _is_food(self, new_position):
        return new_position == self.food_position

    def _collides_with_body(self, new_position):
        return len(self.positions) > MAX_HEAD_OFFSET_CHECK and new_position in self.positions[MAX_HEAD_OFFSET_CHECK:]

    def _update_positions(self, new_position):
        self.positions.insert(0, new_position)
        if len(self.positions) > self.length:
            self.positions.pop()

    def random_food_position(self):
        while self._is_food_in_positions():
            self._set_food_position(self._generate_random_food_position())

    def _is_food_in_positions(self):
        return self.food_position in self.positions

    def _generate_random_food_position(self):
        return (
            random.randint(0, self.screen_width // self.block_size - 1) * self.block_size,
            random.randint(0, self.screen_height // self.block_size - 1) * self.block_size,
        )

    def reset(self):
        self.length = 1
        self.positions = [((self.screen_width / 2), (self.screen_height / 2))]
        self.score = 0
        self.random_food_position()

    def eat_food(self):
        self.length += 1
        self.score += SCORE_PER_FOOD
        self.random_food_position()
